/**
 * Bulk-import the real Steam Workshop catalogue into `GameMod` for the 9
 * families where a Workshop item genuinely installs on a Nxeon dedicated
 * server: ark, unturned, dst, squad, empyrion, soulmask, projectzomboid, tf2,
 * l4d2. Also imports palworld (Workshop is real upstream, just not wired to
 * an install button here — see docs/DOCUMENTATION.md's 2026-09-20 entry).
 * icarus is deliberately excluded: its dedicated server has no Steam Workshop
 * integration at all (confirmed against RocketWerkz's own dedicated-server
 * docs), and a live query against its appid (1149460) returns zero items
 * anyway — there is nothing real to import.
 *
 * SOURCE: Steam Web API's IPublishedFileService/QueryFiles/v1 — a real,
 * documented, key-gated endpoint (STEAM_WEB_API_KEY, already live in
 * production — confirmed today via ISteamWebAPIUtil/GetServerInfo/v1).
 * query_type=9 (k_PublishedFileQueryType_RankedByTotalUniqueSubscriptions)
 * sorts each family's items by subscriber count descending, so paging stops
 * the moment a page drops below the quality floor rather than walking the
 * whole catalogue.
 *
 * APPIDS: Steam Workshop items are filed under the game's CLIENT appid, not
 * a separate "dedicated server" appid — verified empirically against this
 * key (querying a guessed dedicated-server appid for every one of these
 * families returned total:0; the real client appid below is what actually
 * has items, cross-checked against store.steampowered.com/api/appdetails
 * for the exact title match):
 *   ark=346110 (ARK: Survival Evolved) unturned=304930 dst=322330
 *   squad=393380 empyrion=383120 soulmask=2646460 projectzomboid=108600
 *   tf2=440 l4d2=550 palworld=1623730
 *
 * QUALITY THRESHOLD: subscriptions >= 25 (default, override with
 * --min-subscriptions). Modrinth's own import script uses downloads>1000 OR
 * follows>50 because Modrinth's total catalogue is huge (~158k projects) and
 * dominated by noise; Steam Workshop per-family here is a completely
 * different shape — the smallest of these (Squad, ~301 total items as of
 * 2026-09-20) would be reduced to almost nothing under a four-figure floor,
 * while the largest (L4D2, ~220k total items) is exactly the kind of catalog
 * that floor exists to filter. 25 subscribers is deliberately low: it still
 * excludes the long tail of zero/single-digit-subscriber test uploads and
 * reuploads (sampled live: TF2's rank-9000 item sits at 4 subscribers) while
 * keeping every family's real, used content. Also requires `result === 1`
 * (OK — not banned/removed/pending) and `visibility === 0` (public).
 *
 * WHAT THIS DOES NOT FETCH: galleries (Workshop's `previews` array needs a
 * separate per-item call this bulk pass skips, same efficiency tradeoff as
 * Modrinth's importer deferring fileBytes/dependencyCount to
 * verify-gamemods.ts), and `license` (Steam Workshop items never carry one —
 * left null, per the architecture note: this is fetch-only/no-mirror content
 * so a license never applied in the first place).
 *
 * IDEMPOTENT: every write is `db.gameMod.upsert` on the real
 * `@@unique([gameFamily, slug])` constraint.
 *
 *   Dry run, one family, tiny slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-steamworkshop-catalog.ts \
 *       --families=tf2 --max-pages=1
 *
 *   Real write, one family, tiny slice:
 *     NXEON_DB_TARGET=nxeon_staging npx tsx scripts/import-steamworkshop-catalog.ts \
 *       --families=tf2 --max-pages=1 --apply
 *
 *   Full real run (all 10 families, default threshold):
 *     NXEON_DB_TARGET=nxeon npx tsx scripts/import-steamworkshop-catalog.ts --apply
 */

import { assertDbTarget } from "./db-target-guard";
assertDbTarget("import-steamworkshop-catalog.ts");

import { db } from "../lib/db";

const STEAM_KEY = process.env.STEAM_WEB_API_KEY ?? "";
if (!STEAM_KEY) {
  console.error("STEAM_WEB_API_KEY is not set — refusing to run (see .env).");
  process.exit(1);
}
const API = "https://api.steampowered.com";
const PAGE_SIZE = 100; // Steam's real server-side cap on numperpage for this endpoint
const RANKED_BY_TOTAL_UNIQUE_SUBSCRIPTIONS = 9;

const FAMILY_APPID: Record<string, number> = {
  ark: 346110,
  unturned: 304930,
  dst: 322330,
  squad: 393380,
  empyrion: 383120,
  soulmask: 2646460,
  projectzomboid: 108600,
  tf2: 440,
  l4d2: 550,
  palworld: 1623730,
};
const ALL_FAMILIES = Object.keys(FAMILY_APPID);

// ── CLI args ──────────────────────────────────────────────────────────────
function parseArgs(argv: string[]) {
  const get = (name: string) => argv.find((a) => a.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
  const familiesArg = get("families");
  const families = (familiesArg ? familiesArg.split(",") : ALL_FAMILIES).filter((f) => ALL_FAMILIES.includes(f));
  return {
    apply: argv.includes("--apply"),
    minSubscriptions: Number(get("min-subscriptions") ?? 25),
    maxPerFamily: Number(get("max-per-family") ?? 1000),
    ratePerMin: Number(get("rate-per-min") ?? 55), // Steam Web API's documented default cap is ~100k/day per key; stay well under any per-minute burst limit
    maxPages: get("max-pages") ? Number(get("max-pages")) : undefined,
    families: families.length ? families : ALL_FAMILIES,
  };
}

// ── Rate-limited, retrying fetch (same shape as scripts/import-modrinth-catalog.ts) ──
class RateLimiter {
  private minIntervalMs: number;
  private last = 0;
  constructor(perMin: number) {
    this.minIntervalMs = 60_000 / perMin;
  }
  async wait() {
    const now = Date.now();
    const elapsed = now - this.last;
    if (elapsed < this.minIntervalMs) await new Promise((r) => setTimeout(r, this.minIntervalMs - elapsed));
    this.last = Date.now();
  }
}

async function apiFetch(limiter: RateLimiter, url: string, attempt = 1): Promise<Response> {
  await limiter.wait();
  const res = await fetch(url, { headers: { "User-Agent": "Nxeon/1.0 (mods@nxeon.cloud)" } });
  if ((res.status === 429 || res.status >= 500) && attempt <= 5) {
    const backoffMs = 1000 * 2 ** attempt;
    console.warn(`  [retry] HTTP ${res.status} on ${url.replace(STEAM_KEY, "***")} — backing off ${Math.round(backoffMs / 1000)}s`);
    await new Promise((r) => setTimeout(r, backoffMs));
    return apiFetch(limiter, url, attempt + 1);
  }
  return res;
}

// ── Steam types (only the fields we read) ────────────────────────────────
type PublishedFile = {
  result: number;
  publishedfileid: string;
  creator?: string;
  title?: string;
  short_description?: string;
  preview_url?: string;
  subscriptions?: number;
  banned?: boolean;
  visibility?: number;
  time_updated?: number;
};
type QueryFilesResponse = { response: { total?: number; publishedfileditails?: never; publishedfiledetails?: PublishedFile[] } };
type PlayerSummary = { steamid: string; personaname?: string; avatarfull?: string };

function kebab(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 60) || "workshop-item";
}

type Counters = { seen: number; qualified: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
function emptyCounters(): Counters {
  return { seen: 0, qualified: 0, upserted: 0, created: 0, updated: 0, skipped: 0, failed: 0 };
}

async function fetchAuthors(limiter: RateLimiter, steamIds: string[]): Promise<Map<string, PlayerSummary>> {
  const out = new Map<string, PlayerSummary>();
  const unique = [...new Set(steamIds.filter(Boolean))];
  for (let i = 0; i < unique.length; i += 100) {
    const slice = unique.slice(i, i + 100);
    const url = `${API}/ISteamUser/GetPlayerSummaries/v2/?key=${STEAM_KEY}&steamids=${slice.join(",")}`;
    const res = await apiFetch(limiter, url);
    if (!res.ok) continue;
    const body = (await res.json()) as { response?: { players?: PlayerSummary[] } };
    for (const p of body.response?.players ?? []) out.set(p.steamid, p);
  }
  return out;
}

async function importFamily(opts: {
  family: string;
  appid: number;
  limiter: RateLimiter;
  apply: boolean;
  minSubscriptions: number;
  maxPerFamily: number;
  maxPages?: number;
}): Promise<Counters> {
  const { family, appid, limiter, apply, minSubscriptions, maxPerFamily, maxPages } = opts;
  const counters = emptyCounters();
  let cursor = "*";
  let page = 0;
  let total: number | undefined;
  const qualifiedBatch: PublishedFile[] = [];

  for (;;) {
    if (maxPages !== undefined && page >= maxPages) break;
    if (counters.qualified >= maxPerFamily) break;

    const url =
      `${API}/IPublishedFileService/QueryFiles/v1/` +
      `?key=${STEAM_KEY}&appid=${appid}&numperpage=${PAGE_SIZE}&cursor=${encodeURIComponent(cursor)}` +
      `&query_type=${RANKED_BY_TOTAL_UNIQUE_SUBSCRIPTIONS}&return_short_description=true&format=json`;
    const res = await apiFetch(limiter, url);
    page++;
    if (!res.ok) {
      console.error(`  [${family}] HTTP ${res.status} at page ${page} — stopping this family early`);
      break;
    }
    const body = (await res.json()) as QueryFilesResponse & { response: { next_cursor?: string } };
    const items = body.response.publishedfiledetails ?? [];
    total = body.response.total ?? total;
    counters.seen += items.length;
    if (items.length === 0) break;

    let sawBelowFloor = false;
    for (const item of items) {
      if (item.result !== 1 || item.banned || (item.visibility ?? 0) !== 0) continue;
      const subs = item.subscriptions ?? 0;
      if (subs < minSubscriptions) {
        sawBelowFloor = true;
        break; // sorted descending by subscriptions — nothing after this qualifies either
      }
      if (!item.title || !item.publishedfileid) continue;
      qualifiedBatch.push(item);
      counters.qualified++;
      if (counters.qualified >= maxPerFamily) break;
    }

    const nextCursor = (body.response as { next_cursor?: string }).next_cursor;
    console.log(
      `  [${family}] page=${page} fetched=${items.length} qualified_running=${counters.qualified} total=${total ?? "?"}`
    );
    if (sawBelowFloor || !nextCursor || nextCursor === cursor) break;
    cursor = nextCursor;
  }

  if (qualifiedBatch.length === 0) {
    console.log(`  [${family}] nothing qualified (floor=${minSubscriptions} subscribers)`);
    return counters;
  }

  if (!apply) {
    counters.upserted = qualifiedBatch.length;
    return counters;
  }

  const authors = await fetchAuthors(limiter, qualifiedBatch.map((i) => i.creator ?? ""));
  const CONCURRENCY = 8;
  for (let i = 0; i < qualifiedBatch.length; i += CONCURRENCY) {
    const slice = qualifiedBatch.slice(i, i + CONCURRENCY);
    await Promise.all(
      slice.map(async (item) => {
        const publishedFileId = item.publishedfileid;
        const slug = `${kebab(item.title!)}-${publishedFileId.slice(-6)}`;
        const author = item.creator ? authors.get(item.creator) : undefined;
        const data = {
          name: item.title!,
          category: "Workshop",
          description: item.short_description || null,
          iconUrl: item.preview_url || null,
          url: `https://steamcommunity.com/sharedfiles/filedetails/?id=${publishedFileId}`,
          downloads: item.subscriptions ?? null,
          license: null,
          serverSide: null,
          galleryUrls: [] as string[],
          authorName: author?.personaname ?? null,
          authorAvatarUrl: author?.avatarfull ?? null,
          source: "steam_workshop",
          sourceId: publishedFileId,
          active: true,
          verifiedAt: new Date(),
          upstreamOk: true,
          upstreamNote: null,
        };
        try {
          const existing = await db.gameMod.findUnique({
            where: { gameFamily_slug: { gameFamily: family, slug } },
            select: { id: true },
          });
          await db.gameMod.upsert({
            where: { gameFamily_slug: { gameFamily: family, slug } },
            update: data,
            create: { gameFamily: family, slug, ...data },
          });
          counters.upserted++;
          if (existing) counters.updated++;
          else counters.created++;
        } catch (e) {
          counters.failed++;
          console.error(`  [db] ${family}/${slug} failed:`, e instanceof Error ? e.message : e);
        }
      })
    );
  }
  return counters;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  console.log(
    `[import-steamworkshop-catalog] ${args.apply ? "APPLY (writing)" : "DRY RUN (no writes)"} — ` +
      `families: ${args.families.join(", ")}; threshold: subscriptions>=${args.minSubscriptions}; ` +
      `max-per-family=${args.maxPerFamily}; rate=${args.ratePerMin}/min${args.maxPages ? `; max-pages=${args.maxPages} (smoke test)` : ""}`
  );

  const limiter = new RateLimiter(args.ratePerMin);
  const totals = emptyCounters();
  const perFamily: Record<string, Counters> = {};

  for (const family of args.families) {
    console.log(`\n=== ${family} (appid ${FAMILY_APPID[family]}) ===`);
    const counters = await importFamily({
      family,
      appid: FAMILY_APPID[family],
      limiter,
      apply: args.apply,
      minSubscriptions: args.minSubscriptions,
      maxPerFamily: args.maxPerFamily,
      maxPages: args.maxPages,
    });
    perFamily[family] = counters;
    for (const k of Object.keys(totals) as (keyof Counters)[]) totals[k] += counters[k];
    console.log(
      `--- ${family} done: seen=${counters.seen} qualified=${counters.qualified} upserted=${counters.upserted} created=${counters.created} updated=${counters.updated} failed=${counters.failed} ---`
    );
  }

  console.log(`\n============================================================`);
  console.log(`FINAL SUMMARY (${args.apply ? "APPLIED" : "DRY RUN — nothing written"})`);
  for (const family of args.families) {
    const c = perFamily[family]!;
    console.log(
      `  ${family.padEnd(15)} seen=${c.seen.toString().padStart(6)} qualified=${c.qualified.toString().padStart(5)} upserted=${c.upserted.toString().padStart(5)} created=${c.created.toString().padStart(5)} updated=${c.updated.toString().padStart(5)} failed=${c.failed}`
    );
  }
  console.log(
    `  ${"TOTAL".padEnd(15)} seen=${totals.seen.toString().padStart(6)} qualified=${totals.qualified.toString().padStart(5)} upserted=${totals.upserted.toString().padStart(5)} created=${totals.created.toString().padStart(5)} updated=${totals.updated.toString().padStart(5)} failed=${totals.failed}`
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

