1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { connectionTarget, serverRootPassword } from "../lib/sftp";
4	import { INSTALLABLE_FAMILIES, RESOLVABLE_SOURCES } from "../lib/mod-install-support";
5	import { Client, type ClientChannel } from "ssh2";
6	import type { Job } from "@prisma/client";
7	
8	/**
9	 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
10	 * state recorded in `ServerMod` rows:
11	 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
12	 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
13	 *
14	 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
15	 *
16	 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
17	 * mod is installed when nothing was written to their server:
18	 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
19	 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
20	 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
21	 *    FAILED with a clear reason — never silently "INSTALLED".
22	 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
23	 *    message. A change we did NOT apply is a failure and must say so.
24	 */
25	
26	const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";
27	
28	async function notify(userId: string, title: string, body?: string, href?: string) {
29	  try {
30	    await db.notification.create({ data: { userId, title, body, href } });
31	  } catch (e) {
32	    console.error("[game-mods] notify failed", e);
33	  }
34	}
35	
36	export async function gameModSync(job: Job): Promise<void> {
37	  const serverId = job.serverId;
38	  if (!serverId) throw new Error("game mod sync: job has no serverId");
39	
40	  const server = await db.server.findUnique({
41	    where: { id: serverId },
42	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
43	  });
44	  if (!server) throw new Error(`Server ${serverId} not found`);
45	
46	  const pending = await db.serverMod.findMany({
47	    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
48	    include: { mod: true },
49	  });
50	  if (pending.length === 0) return;
51	
52	  const installedNames: string[] = [];
53	  const removedNames: string[] = [];
54	  const failedNames: string[] = [];
55	
56	  for (const sm of pending) {
57	    const removing = sm.status === "REMOVING";
58	    try {
59	      if (SANDBOX) {
60	        // Dev simulation — no VM mutation.
61	        if (removing) {
62	          await db.serverMod.delete({ where: { id: sm.id } });
63	          removedNames.push(sm.mod.name);
64	        } else {
65	          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
66	          installedNames.push(sm.mod.name);
67	        }
68	        continue;
69	      }
70	
71	      if (!REAL_ENABLED) {
72	        // Honest failure: nothing was applied. Do NOT report success.
73	        await db.serverMod.update({
74	          where: { id: sm.id },
75	          data: {
76	            status: "FAILED",
77	            error:
78	              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
79	          },
80	        });
81	        failedNames.push(sm.mod.name);
82	        continue;
83	      }
84	
85	      // REAL path — install/remove over SSH via the per-source adapter.
86	      const modRow: ModRowFull = {
87	        gameFamily: sm.mod.gameFamily,
88	        source: sm.mod.source,
89	        sourceId: sm.mod.sourceId,
90	        slug: sm.mod.slug,
91	        name: sm.mod.name,
92	        url: sm.mod.url,
93	        variant: server.gameVariant ?? null,
94	        appliesTo: sm.mod.appliesToVariant ?? null,
95	      };
96	      const result = removing ? await removeModReal(server, modRow) : await installModReal(server, modRow);
97	
98	      if (result.ok) {
99	        if (removing) {
100	          await db.serverMod.delete({ where: { id: sm.id } });
101	          removedNames.push(sm.mod.name);
102	        } else {
103	          await db.serverMod.update({
104	            where: { id: sm.id },
105	            data: { status: "INSTALLED", version: result.version ?? null, error: null },
106	          });
107	          installedNames.push(sm.mod.name);
108	        }
109	      } else {
110	        await db.serverMod.update({
111	          where: { id: sm.id },
112	          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
113	        });
114	        failedNames.push(sm.mod.name);
115	      }
116	    } catch (e) {
117	      const msg = e instanceof Error ? e.message : String(e);
118	      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
119	      await db.serverMod.update({
120	        where: { id: sm.id },
121	        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
122	        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
123	      });
124	      failedNames.push(sm.mod.name);
125	    }
126	  }
127	
128	  // One summary notification for the batch.
129	  const parts: string[] = [];
130	  if (installedNames.length) parts.push(`installed ${installedNames.join(", ")}`);
131	  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
132	  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
133	  const anyOk = installedNames.length > 0 || removedNames.length > 0;
134	  const allFailed = !anyOk && failedNames.length > 0;
135	
136	  await notify(
137	    server.userId,
138	    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
139	    parts.length ? `${parts.join("; ")}.` : "No changes were made.",
140	    `/dashboard/servers/${server.id}?tab=mods`
141	  );
142	}
143	
144	// ===========================================================================
145	// Real install/remove — per-source adapters over SSH.
146	//
147	// Approach: the worker resolves a DIRECT download URL from the source's API, then
148	// SSHes into the game VM and has the VM itself `curl` the file into the game's
149	// plugin/mod directory (deterministic filename, so uninstall is a plain rm — no
150	// per-install state to track). Sources that need auth or per-repo handling
151	// (GitHub release zips, Nexus, CurseForge key, Codefling paid) soft-fail with a
152	// clear "install manually from <url>" note rather than faking success.
153	//
154	// Supported today: modrinth + spigotmc (Minecraft), umod (Rust), thunderstore
155	// (Valheim) — which fully covers those three games' catalogs.
156	// ===========================================================================
157	
158	type ModResult = { ok: boolean; version?: string; error?: string };
159	type ModRow = {
160	  gameFamily: string;
161	  source: string;
162	  sourceId: string | null;
163	  slug: string;
164	  name: string;
165	  url: string | null;
166	};
167	type SshServer = {
168	  id: string;
169	  rootPassword: string | null;
170	  rootPasswordEnc?: string | null;
171	  sshPort: number | null;
172	  dedicatedIp?: { address: string } | null;
173	  node?: { publicIp: string } | null;
174	};
175	
176	const CONNECT_TIMEOUT_MS = 15_000;
177	const EXEC_TIMEOUT_MS = 200_000; // downloads can be large
178	
179	/** PascalCase a mod name for an Oxide/Carbon .cs filename (class-name convention). */
180	function pascal(name: string): string {
181	  const p = name.replace(/[^a-zA-Z0-9]+/g, " ").trim().split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
182	  return p || "Plugin";
183	}
184	
185	/** Deterministic on-disk target for a mod, or null if its source isn't installable. */
186	function planTarget(mod: ModRow): { kind: "jar" | "cs" | "zip"; file?: string; folder?: string } | null {
187	  switch (mod.source) {
188	    case "modrinth":
189	    case "spigotmc":
190	      return { kind: "jar", file: `nxeon-${mod.slug}.jar` };
191	    case "umod":
192	      return { kind: "cs", file: `${pascal(mod.name)}.cs` };
193	    case "thunderstore":
194	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
195	    case "github":
196	      // Same "zip-of-a-folder" shape as thunderstore — a reasonable generic
197	      // default for a GitHub release asset, but untested against a real CS2
198	      // plugin's actual archive layout (addons/ layout vs. a bare .dll/.so vs.
199	      // a source tarball all differ per repo). Harmless today: no family in
200	      // INSTALLABLE_FAMILIES is github-sourced (see mod-install-support.ts),
201	      // so modDirShell always returns null first and this never actually runs
202	      // an install. Revisit this specific shape when a family is wired up.
203	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
204	    default:
205	      return null; // nexus / curseforge / codefling / hangar — manual
206	  }
207	}
208	
209	/** Resolve a direct download URL from the source's API (worker-side). */
210	async function resolveUrl(mod: ModRowFull): Promise<string | null> {
211	  const id = mod.sourceId ?? "";
212	  try {
213	    switch (mod.source) {
214	      case "umod":
215	        return `https://umod.org/plugins/${id}.cs`;
216	      case "spigotmc":
217	        return `https://api.spiget.org/v2/resources/${id}/download`;
218	      case "modrinth": {
219	        const loader = modrinthLoader(mod);
220	        const q = loader ? `?loaders=["${loader}"]` : "";
221	        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
222	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
223	        });
224	        if (!res.ok) return null;
225	        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
226	        const v = versions[0];
227	        if (!v) return null;
228	        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
229	      }
230	      case "thunderstore": {
231	        const [author, ...rest] = id.split("-");
232	        if (!rest.length) return null;
233	        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
234	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
235	        });
236	        if (!res.ok) return null;
237	        const pkg = (await res.json()) as { latest?: { download_url?: string } };
238	        return pkg.latest?.download_url ?? null;
239	      }
240	      case "github": {
241	        // id is "owner/repo" (scripts/import-github-catalog.ts's sourceId
242	        // convention, matching prisma/seed-gamemods.ts's pre-existing CS2
243	        // rows). Resolved fresh at install time, same as modrinth above —
244	        // nothing about the release is cached on the GameMod row, so a mod
245	        // author cutting a new release just works with no re-import needed.
246	        const headers: Record<string, string> = { "User-Agent": "Nxeon/1.0 (mod-manager)", Accept: "application/vnd.github+json" };
247	        if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
248	        const res = await fetch(`https://api.github.com/repos/${id}/releases/latest`, { headers });
249	        if (!res.ok) return null; // no releases yet, repo renamed/gone, or rate-limited
250	        const release = (await res.json()) as { assets?: Array<{ browser_download_url: string; name: string }> };
251	        const assets = release.assets ?? [];
252	        if (assets.length === 0) return null;
253	        // Prefer a real packaged archive over a loose source-only asset when both exist.
254	        const archive = assets.find((a) => /\.(zip|tar\.gz|tgz)$/i.test(a.name));
255	        return (archive ?? assets[0]).browser_download_url;
256	      }
257	      default:
258	        return null;
259	    }
260	  } catch (e) {
261	    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
262	    return null;
263	  }
264	}
265	
266	function modrinthLoader(mod: ModRowFull): string | null {
267	  // Prefer the mod's own loader target; fall back to the server's variant.
268	  const key = mod.appliesTo ?? mod.variant ?? "";
269	  const map: Record<string, string> = {
270	    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
271	    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
272	  };
273	  return map[key] ?? null;
274	}
275	
276	/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
277	/* The shared set in lib/mod-install-support.ts is what the PANEL uses to decide
278	   whether to draw an Install button at all. If this switch ever grows a case
279	   that isn't in that set the button never appears, and if the set grows a
280	   family this switch doesn't handle the button appears and fails — which is the
281	   bug that module was written to end. Fail loudly here rather than let them
282	   drift apart silently. */
283	function modDirShell(family: string, variant: string | null): string | null {
284	  if (!INSTALLABLE_FAMILIES.has(family)) return null;
285	  switch (family) {
286	    case "minecraft": {
287	      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
288	      const sub = modded ? "mods" : "plugins";
289	      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
290	    }
291	    case "rust":
292	      return `d=$(find /opt /srv /home -maxdepth 9 -type d \\( -name oxide -o -name carbon \\) 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
293	    // Was a case-sensitive `find -name BepInEx` — always a no-op even with
294	    // BepInEx installed, since lloesche/valheim-server's own real directory is
295	    // lowercase `bepinex` (confirmed against its README). Use the documented,
296	    // fixed path directly instead of searching for it: `/config` is the
297	    // catalog's own `-v /opt/valheim/config:/config` mount, and the image
298	    // itself watches `/config/bepinex/plugins` for user-added plugins and
299	    // copies them into the real BepInEx plugin dir on boot — this is the
300	    // customer-facing "drop mods here" folder by design, not an internal path.
301	    case "valheim":
302	      return `d=/opt/valheim/config/bepinex/plugins; [ -d /opt/valheim/config/bepinex ] && { mkdir -p "$d"; echo "$d"; }`;
303	    default:
304	      return null;
305	  }
306	}
307	
308	const shq = (s: string) => s.replace(/'/g, "'\\''");
309	
310	async function installModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
311	  const target = planTarget(mod);
312	  if (!target) {
313	    return { ok: false, error: `Auto-install isn't available for ${mod.source} mods yet — install manually${mod.url ? ` from ${mod.url}` : ""}.` };
314	  }
315	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
316	  if (!dirShell) {
317	    return { ok: false, error: `Auto-install isn't wired for this game yet.` };
318	  }
319	  if (!RESOLVABLE_SOURCES.has(mod.source)) {
320	    return { ok: false, error: `We can't fetch downloads from ${mod.source} — install this one by hand in Files.` };
321	  }
322	  const url = await resolveUrl(mod);
323	  if (!url) return { ok: false, error: "Could not resolve a download for this mod (it may have moved)." };
324	
325	  let cmd: string;
326	  if (target.kind === "zip") {
327	    cmd =
328	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
329	      `tmp=$(mktemp -d); if curl -fsSL --max-time 180 -o "$tmp/m.zip" '${shq(url)}'; then ` +
330	      `rm -rf "$dir/${target.folder}"; mkdir -p "$dir/${target.folder}"; ` +
331	      `unzip -oq "$tmp/m.zip" -d "$dir/${target.folder}" && echo OK || echo UNZIP; rm -rf "$tmp"; else echo FAIL; fi`;
332	  } else {
333	    cmd =
334	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
335	      `if curl -fsSL --max-time 180 -o "$dir/${target.file}" '${shq(url)}'; then echo OK; else echo FAIL; fi`;
336	  }
337	
338	  const out = await withSsh(server, (conn) => execRemote(conn, cmd));
339	  const s = out.stdout.trim();
340	  if (s.endsWith("OK")) return { ok: true };
341	  if (s.includes("NODIR")) return { ok: false, error: "Couldn't find the game's mod folder — is the server fully set up?" };
342	  if (s.includes("UNZIP")) return { ok: false, error: "Downloaded the mod but couldn't unpack it (unzip missing?)." };
343	  return { ok: false, error: "Download failed on the server." };
344	}
345	
346	async function removeModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
347	  const target = planTarget(mod);
348	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
349	  if (!target || !dirShell) return { ok: true }; // nothing we placed → nothing to remove
350	  const rm =
351	    target.kind === "zip"
352	      ? `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -rf "$dir/${target.folder}"; echo OK`
353	      : `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -f "$dir/${target.file}"; echo OK`;
354	  await withSsh(server, (conn) => execRemote(conn, rm));
355	  return { ok: true };
356	}
357	
358	// --- SSH transport (root@VM, password from the same source as the file manager) ---
359	
360	type ModRowFull = ModRow & { variant: string | null; appliesTo: string | null };
361	
362	function withSsh<T>(server: SshServer, fn: (conn: Client) => Promise<T>): Promise<T> {
363	  return new Promise((resolve, reject) => {
364	    const t = connectionTarget(server as any);
365	    if (!t) return reject(new Error("server is not reachable yet"));
366	    const password = serverRootPassword(server as any);
367	    if (!password) return reject(new Error("server has no root password set"));
368	    const conn = new Client();
369	    let settled = false;
370	    const finish = (err: Error | null, val?: T) => {
371	      if (settled) return;
372	      settled = true;
373	      try { conn.end(); } catch { /* best-effort */ }
374	      err ? reject(err) : resolve(val as T);
375	    };
376	    conn.on("ready", () => {
377	      fn(conn).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
378	    });
379	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
380	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
381	  });
382	}
383	
384	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
385	  return new Promise((resolve, reject) => {
386	    conn.exec(cmd, (err, stream: ClientChannel) => {
387	      if (err) return reject(err);
388	      let stdout = "";
389	      let stderr = "";
390	      const timer = setTimeout(() => { try { stream.close(); } catch { /* ignore */ } }, EXEC_TIMEOUT_MS);
391	      stream
392	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, stdout, stderr }); })
393	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
394	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
395	    });
396	  });
397	}
