/** Update `Key=Value` lines in a PZ-style ini, preserving everything else;
 *  append missing keys. Same shape as worker/game-config.ts's
 *  `updateKeyValue` for server.properties — kept as its own copy since that
 *  function isn't exported and this file deliberately doesn't import
 *  low-level helpers from game-config.ts (see the container-recreate
 *  section's comment above). */
function updateIniKeyValue(content: string, updates: Record<string, string>): string {
  const lines = content.split(/\r?\n/);
  const seen = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim();
    if (!t || t.startsWith("#")) continue;
    const eq = lines[i].indexOf("=");
    if (eq < 0) continue;
    const key = lines[i].slice(0, eq).trim();
    if (Object.prototype.hasOwnProperty.call(updates, key)) {
      lines[i] = `${key}=${updates[key]}`;
      seen.add(key);
    }
  }
  for (const k of Object.keys(updates)) {
    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
  }
  return lines.join("\n");
}

/**
 * Project Zomboid needs BOTH the numeric Workshop id (`WorkshopItems=`) AND
 * the mod's own internal string id from its `mod.info` file (`Mods=`) — two
 * different values, confirmed against PZwiki. The Workshop API never exposes
 * the second one; the only way to learn it is to look inside the mod's own
 * files. We do that with a single, throwaway `steamcmd workshop_download_item`
 * run INSIDE the customer's own container (Valve's own tool, on their own
 * VM — not a Nxeon download/mirror), read `mod.info`, then delete what we
 * fetched immediately — the dedicated server re-fetches its own real copy on
 * boot via `WorkshopItems=`, so nothing is kept or served from here. The
 * result is cached onto the `GameMod` row so this only ever runs once per
 * mod, for any server.
 */
async function resolvePzModStringId(conn: Client, sourceId: string): Promise<string | null> {
  const tmp = `/tmp/nxw-${sourceId.replace(/[^0-9]/g, "")}`;
  const cmd =
    `docker exec projectzomboid steamcmd +login anonymous +force_install_dir '${shq(tmp)}' +workshop_download_item ${PZ_APPID} ${shq(sourceId)} +quit >/dev/null 2>&1; ` +
    `docker exec projectzomboid sh -c "find '${shq(tmp)}' -iname mod.info 2>/dev/null | head -5 | xargs -r cat" 2>/dev/null; ` +
    `docker exec projectzomboid rm -rf '${shq(tmp)}' >/dev/null 2>&1`;
  const { stdout } = await execRemote(conn, cmd);
  const ids = [...stdout.matchAll(/^\s*id\s*=\s*(.+?)\s*$/gim)].map((m) => m[1].trim()).filter(Boolean);
  return ids.length ? ids.join(";") : null;
}

const PZ_APPID = WORKSHOP_APPID.projectzomboid;

async function applyProjectZomboidWorkshop(
  server: SshServer,
  mods: { sourceId: string; modStringId: string | null; gameModId: string }[]
): Promise<ModResult> {
  return withSftp(server, async (conn, sftp) => {
    const resolved: string[] = [];
    for (const m of mods) {
      if (m.modStringId) {
        resolved.push(m.modStringId);
        continue;
      }
      const found = await resolvePzModStringId(conn, m.sourceId);
      if (!found) {
        return {
          ok: false,
          error: `Could not read this mod's internal Mod ID from Steam Workshop item ${m.sourceId} — it may be private, removed, or not a real PZ mod.`,
        };
      }
      await db.gameMod.update({ where: { id: m.gameModId }, data: { modStringId: found }, select: { id: true } }).catch(() => {});
      resolved.push(found);
    }

    const dir = "/opt/projectzomboid/config/Server";
    await execRemote(conn, `mkdir -p '${shq(dir)}'`);
    // SERVER_NAME=servertest, fixed by this platform's projectzomboid setupScript (prisma/seed-wave1/7-games.ts).
    const path = `${dir}/servertest.ini`;
    const existing = (await sftpRead(sftp, path)) ?? "";
    const updated = updateIniKeyValue(existing, {
      WorkshopItems: mods.map((m) => m.sourceId).join(";"),
      Mods: resolved.join(";"),
    });
    await sftpWrite(sftp, path, updated);
    return { ok: true };
  });
}

function stripMarkedBlock(content: string, start: string, end: string): string {
  const s = content.indexOf(start);
  if (s < 0) return content;
  const e = content.indexOf(end, s);
  if (e < 0) return content;
  return content.slice(0, s) + content.slice(e + end.length);
}

const TF2_MARKER_START = "// === NXEON WORKSHOP MAPS (managed — do not edit below) ===";
const TF2_MARKER_END = "// === END NXEON WORKSHOP MAPS ===";

/** TF2 — `tf_workshop_map_sync <id>` lines appended to `tf/cfg/server.cfg`
 *  (executed by the game on config-exec/map-load; this specific TF2 command,
 *  not CS2's `host_workshop_collection`, is what actually works for this
 *  game — confirmed via the long-standing Valve-endorsed community guide,
 *  since wiki.teamfortress.com has no Workshop page of its own). GATED: the
 *  dedicated server cannot fetch ANY Workshop map without a real
 *  `SRCDS_WORKSHOP_AUTHKEY` set on the container (cm2network/tf2's own
 *  documented requirement) — Nxeon does not provision one today, so this
 *  fails honestly rather than writing a config line that silently never
 *  activates. */
async function applyTf2Workshop(server: SshServer, ids: string[]): Promise<ModResult> {
  return withSftp(server, async (conn, sftp) => {
    const envMap = await readEnvMap(conn, "tf2");
    const authKey = envMap?.get("SRCDS_WORKSHOP_AUTHKEY");
    if (!authKey) {
      return {
        ok: false,
        error:
          "This server doesn't have a Steam Workshop Auth Key configured yet, which TF2 requires to fetch Workshop maps — contact support to have one added, then try again.",
      };
    }
    const path = "/opt/tf2/tf/cfg/server.cfg";
    const existing = (await sftpRead(sftp, path)) ?? "";
    const withoutOld = stripMarkedBlock(existing, TF2_MARKER_START, TF2_MARKER_END);
    const block = [TF2_MARKER_START, ...ids.map((id) => `tf_workshop_map_sync ${id}`), TF2_MARKER_END].join("\n");
    await sftpWrite(sftp, path, `${withoutOld.trimEnd()}\n\n${block}\n`);
    return { ok: true };
  });
}

/**
 * L4D2 — NOT pure config-write (confirmed via AlliedModders, the authoritative
 * community source for Source-engine dedicated-server administration): the
 * VPK must physically exist under `addons/` before `addonlist.txt` referencing
 * it does anything. We fetch it with `steamcmd workshop_download_item` run
 * INSIDE the customer's own container — Valve's own tool, pulling straight
 * from Steam's CDN — never a Nxeon-hosted copy. left4devops/l4d2 exposes
 * `/addons` as the only persisted, bind-mounted directory
 * (`/opt/l4d2/addons` on the host), which is where both the fetched .vpk
 * files and addonlist.txt live.
 *
 * CONFIDENCE NOTE: this image documents no Workshop-specific env var at all
 * (checked directly against its Docker Hub page), so the exact expected
 * location/format of `addonlist.txt` for THIS SPECIFIC image is inferred
 * from the general L4D2 dedicated-server convention, not confirmed against
 * this image's own source — flagged here and in the delivery report rather
 * than presented as verified.
 */
const L4D2_APPID = WORKSHOP_APPID.l4d2;

async function applyL4d2Workshop(server: SshServer, ids: string[]): Promise<ModResult> {
  return withSftp(server, async (conn, sftp) => {
    for (const id of ids) {
      const check = await execRemote(conn, `[ -f '/opt/l4d2/addons/${shq(id)}.vpk' ] && echo YES`);
      if (check.stdout.trim() === "YES") continue; // already fetched

      const tmp = `/tmp/nxw-${id}`;
      await execRemote(
        conn,
        `docker exec l4d2 steamcmd +login anonymous +force_install_dir '${shq(tmp)}' +workshop_download_item ${L4D2_APPID} ${shq(id)} +quit >/dev/null 2>&1`
      );
      const found = await execRemote(conn, `docker exec l4d2 sh -c "find '${shq(tmp)}' -iname '*.vpk' 2>/dev/null | head -1"`);
      const vpkPath = found.stdout.trim();
      if (vpkPath) {
        await execRemote(conn, `docker exec l4d2 cp '${shq(vpkPath)}' /addons/${shq(id)}.vpk`);
      }
      await execRemote(conn, `docker exec l4d2 rm -rf '${shq(tmp)}' >/dev/null 2>&1`);

      const confirm = await execRemote(conn, `[ -f '/opt/l4d2/addons/${shq(id)}.vpk' ] && echo YES`);
      if (confirm.stdout.trim() !== "YES") {
        return { ok: false, error: `Could not fetch Steam Workshop item ${id} for this server — it may be private, removed, or not an L4D2 addon.` };
      }
    }

    // Drop vpks for anything no longer desired.
    const present = await execRemote(conn, `ls /opt/l4d2/addons/*.vpk 2>/dev/null`);
    for (const line of present.stdout.split(/\r?\n/)) {
      const base = line.trim().split("/").pop();
      const id = base?.replace(/\.vpk$/, "");
      if (id && !ids.includes(id)) await execRemote(conn, `rm -f '/opt/l4d2/addons/${shq(id)}.vpk'`);
    }

    const addonlist = ids.map((id) => `addons/${id}.vpk`).join("\n") + (ids.length ? "\n" : "");
    await sftpWrite(sftp, "/opt/l4d2/addons/addonlist.txt", addonlist);
    return { ok: true };
  });
}

/**
 * Empyrion — NOT pure config-write, and NOT a growing list: the official
 * wiki's `dedicated.yaml` reference has exactly one relevant key,
 * `CustomScenario`, and it takes a SINGLE local folder name, not a Workshop
 * id or a list. So unlike every other family here, Empyrion can only have
 * ONE active Workshop scenario at a time — attempting a second install while
 * one is already active is refused rather than silently replacing it.
 *
 * Mechanism: `steamcmd workshop_download_item` (Valve's own tool, run inside
 * the customer's own container — bitr/empyrion-server documents a generic
 * `STEAMCMD=` passthrough env var for exactly this kind of one-off command)
 * fetches the scenario into the container's own workshop content cache; we
 * then copy it into `Content/Scenarios/` under a fixed name and point
 * `dedicated.yaml`'s `CustomScenario` at it.
 *
 * CONFIDENCE NOTE: the exact internal path layout under this image's mounted
 * volume (`/opt/empyrion` on the host, `/home/user/Steam` in the container)
 * is discovered at run time via `find` rather than hardcoded, because no
 * official source documents it precisely — if `dedicated.yaml` or
 * `Content/Scenarios` can't be located, this fails honestly instead of
 * guessing a path and silently writing nothing (or writing to the wrong
 * place).
 */
const EMPYRION_APPID = WORKSHOP_APPID.empyrion;

async function patchEmpyrionScenario(conn: Client, sftp: SFTPWrapper, root: string, scenarioName: string | null): Promise<ModResult> {
  const found = await execRemote(conn, `find '${shq(root)}' -maxdepth 8 -type f -iname 'dedicated.yaml' 2>/dev/null | head -1`);
  const path = found.stdout.trim();
  if (!path) return { ok: false, error: "Could not locate dedicated.yaml on this server — nothing was changed." };
  const existing = await sftpRead(sftp, path);
  if (existing == null) return { ok: false, error: "dedicated.yaml disappeared — nothing was changed." };
  if (!/^\s*CustomScenario\s*:/m.test(existing)) {
    return { ok: false, error: "Could not find a CustomScenario key in dedicated.yaml — set it manually to activate this scenario." };
  }
  const line = scenarioName ? `    CustomScenario: '${scenarioName}'` : `    CustomScenario: ''`;
  const updated = existing.replace(/^\s*CustomScenario\s*:.*$/m, line);
  await sftpWrite(sftp, path, updated);
  return { ok: true };
}

async function applyEmpyrionWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
  if (ids.length > 1) {
    return {
      ok: false,
      error: "Empyrion's dedicated server can only run one active Workshop scenario at a time — remove the current one before adding another.",
    };
  }
  return withSftp(server, async (conn, sftp) => {
    const root = "/opt/empyrion";
    if (ids.length === 0) {
      return patchEmpyrionScenario(conn, sftp, root, null);
    }
    const id = ids[0];
    await execRemote(
      conn,
      `docker exec empyrion steamcmd +login anonymous +force_install_dir /home/user/Steam +workshop_download_item ${EMPYRION_APPID} ${shq(id)} +quit >/dev/null 2>&1`
    );
    const found = await execRemote(
      conn,
      `find '${shq(root)}/steamapps/workshop/content/${EMPYRION_APPID}/${shq(id)}' -maxdepth 1 -type d 2>/dev/null | head -1`
    );
    const contentDir = found.stdout.trim();
    if (!contentDir) {
      return { ok: false, error: `Could not fetch Steam Workshop scenario ${id} — it may be private, removed, or not an Empyrion scenario.` };
    }
    const scenariosDirRes = await execRemote(conn, `find '${shq(root)}' -maxdepth 8 -type d -path '*/Content/Scenarios' 2>/dev/null | head -1`);
    const scenariosDir = scenariosDirRes.stdout.trim();
    if (!scenariosDir) {
      return { ok: false, error: "Could not locate this server's Content/Scenarios directory — nothing was changed." };
    }
    const scenarioName = `nxw-${id}`;
    await execRemote(
      conn,
      `rm -rf '${shq(scenariosDir)}/${shq(scenarioName)}' && cp -r '${shq(contentDir)}' '${shq(scenariosDir)}/${shq(scenarioName)}'`
    );
    return patchEmpyrionScenario(conn, sftp, root, scenarioName);
  });
}

